const COMMON=[
 'You are auditing the Maui/Oahu dataset of the OceanSafe visitor app. Visitors follow these listings in person; closed businesses or wrong sites are trust failures. Post-Aug-2023 Lahaina-fire closures are especially likely on West Maui.',
 'READ-ONLY: research and RETURN results. Do NOT edit, write, or modify any file, and do not run file-mutating commands.',
 'For EACH item: (1) verify it is OPEN and operating in mid-2026 (Yelp/Google/official/news, 2025-2026 signals; look for CLOSED markers). (2) website: linkStatus 200 does not prove correctness - confirm the URL is the business own official site, not hijacked/parked/unrelated; a 403 linkStatus usually just means bot-blocking, verify the site is genuine. If NO website is stored and an official one exists, websiteAction=add with the URL. (3) note materially changed hours.',
 'Farmers markets: verify the market still runs on its stated day. Hikes/trails: verify open vs closed (DLNR/NPS closures, post-storm).',
 'Be honest: status=unverifiable with low confidence beats guessing. Cite what you saw, with dates.',
].join('\n');
phase('Verify')
const results = await pipeline(BUCKETS,
 (b)=>agent([COMMON,'','BUCKET: '+b.key+' (island: '+b.island+')','ITEMS:',JSON.stringify(b.items,null,1),'','Return one result per item (ALL of them).'].join('\n'),
   {label:'verify:'+b.key,phase:'Verify',agentType:'Explore',schema:RES_SCHEMA,effort:'medium'}).then(r=>({b,r})),
 ({b,r})=>{
   if(!r) return {key:b.key,island:b.island,results:null,closures:null};
   const flagged=r.results.filter(x=>x.status==='closed'||x.status==='moved_or_renamed');
   if(!flagged.length) return {key:b.key,island:b.island,results:r.results,closures:{rulings:[]}};
   return agent(['You are an adversarial checker. A researcher claims these '+b.island+' businesses are CLOSED or moved. REFUTE if you can - removing a live business is also a failure. Re-verify independently (2025-2026 signals). READ-ONLY.','Claims:',JSON.stringify(flagged,null,1),'Rule each: confirm_closed / actually_open (with correctWebsite if any) / uncertain.'].join('\n'),
     {label:'confirm:'+b.key,phase:'Confirm closures',agentType:'Explore',schema:VER_SCHEMA,effort:'high'}).then(v=>({key:b.key,island:b.island,results:r.results,closures:v}));
 })
return results.filter(Boolean)